cmn_relative_duration.script:
// Perform relative duration calculation using the 'calculator' variable (which is a DurationCalculator object)

(function() {

	//get the NDB notification SLA
	var durationHours = Number(gs.getProperty('x_1776078_cyber_0.sla.ndb_notification_hours'));
	var dueTime = new GlideDateTime(calculator.startDateTime);
	dueTime.addSeconds(durationHours * 3600);

    // set the endDateTime property of the calculator object
    calculator.endDateTime = dueTime;
    calculator.calcScheduleDuration();
})();
